final class DoctrineSyllabusEvidenceRetriever implements SyllabusEvidenceRetrieverInterface { public function __construct(private readonly EntityManagerInterface $entityManager){} public function listAvailable():array{return array_map(static fn(array $row)=>new \App\Domain\Assistant\ValueObject\AvailableSyllabus((string)$row['id'],(string)$row['name']),$this->entityManager->createQueryBuilder()->select('DISTINCT s.id, s.name')->from(\App\Infrastructure\Persistence\Doctrine\Catalog\Entity\SyllabusRecord::class,'s')->innerJoin(SyllabusDocumentExtractionRecord::class,'e','WITH','e.syllabusId=s.id')->orderBy('s.name','ASC')->getQuery()->getArrayResult());} public function retrieve(string $syllabusId,string $query,int $limit=3):array{$rows=$this->entityManager->createQueryBuilder()->select('e')->from(SyllabusDocumentExtractionRecord::class,'e')->where('e.syllabusId=:id')->setParameter('id',$syllabusId)->orderBy('e.pageNumber','ASC')->getQuery()->getResult();$terms=array_values(array_filter(preg_split('/[^[:alnum:]]+/u',mb_strtolower($query))?:[],static fn(string $term)=>mb_strlen($term)>=3));usort($rows,static function($a,$b)use($terms):int{$score=static fn($r)=>array_sum(array_map(static fn($t)=>substr_count(mb_strtolower($r->textContent),$t),$terms));return $score($b)<=>$score($a)?:$a->pageNumber<=>$b->pageNumber;});$out=[];foreach(array_slice($rows,0,$limit) as $row){$text=trim(preg_replace('/\s+/u',' ',$row->textContent)??'');if($text!=='')$out[]=new SyllabusEvidence($row->pageNumber,mb_substr($text,0,700));}return $out;} }
